"""Toy model (idea 001): blur of lattice points generated by coupling.

Quantum chain of N masses + springs, periodic. Units: hbar = m = a = kappa = 1 (so c = 1).
Ground-state (zero-point) fluctuations:
  blur^2      = <u_n^2>              = (1/N) sum_{k!=0} 1/(2 w_k)
  relative^2  = <(u_{n+r} - u_n)^2>  = (1/N) sum_{k!=0} (1 - cos(q_k r)) / w_k
with w_k = 2|sin(q_k/2)|, q_k = 2 pi k / N.  (k = 0 is the centre-of-mass mode, dropped.)
"""
import numpy as np

def modes(N):
    k = np.arange(1, N)
    q = 2 * np.pi * k / N
    return q, 2 * np.abs(np.sin(q / 2))

def blur2(N):
    q, w = modes(N)
    return np.sum(1 / (2 * w)) / N

def rel2(N, r):
    q, w = modes(N)
    return np.sum((1 - np.cos(q * r)) / w) / N

def blur2_3d(N):
    k = np.arange(N)
    q = 2 * np.pi * k / N
    s2 = 4 * np.sin(q / 2) ** 2
    W = np.sqrt(s2[:, None, None] + s2[None, :, None] + s2[None, None, :])
    W[0, 0, 0] = np.inf
    return np.sum(1 / (2 * W)) / N**3

if __name__ == "__main__":
    print("1D chain: absolute blur^2 vs ln(N)/(2 pi)")
    for N in [10, 100, 1_000, 10_000, 100_000, 1_000_000]:
        b = blur2(N)
        print(f"  N={N:>9,}  blur^2={b:.4f}  ln(N)/2pi={np.log(N)/(2*np.pi):.4f}  diff={b - np.log(N)/(2*np.pi):.4f}")
    print("\n1D chain (N=100,000): relative blur^2 between sites r apart vs ln(r)/pi")
    for r in [1, 2, 10, 100, 1000, 10000]:
        d = rel2(100_000, r)
        print(f"  r={r:>6}  rel^2={d:.4f}  ln(r)/pi={np.log(r)/np.pi:.4f}  diff={d - np.log(r)/np.pi:.4f}")
    print("\n3D cubic lattice: absolute blur^2 (should saturate)")
    for N in [4, 8, 16, 32, 64]:
        print(f"  N={N:>3}^3  blur^2={blur2_3d(N):.4f}")
